export const THEME_CATALOG = {
  APPOINTMENT: APPOINTMENT_CATALOG,
  ECOMMERCE: ECOMMERCE_CATALOG,
  STATIC: STATIC_CATALOG,
};

// Returns [{ label, themes: [{key,label,icon,desc}] }] - only available
// themes, only non-empty groups. Used by the onboarding industry picker.
export function getAvailableGroups(vertical) {
  const cat = THEME_CATALOG[vertical] || {};
  return Object.entries(cat)
    .map(([label, themes]) => ({ label, themes: themes.filter((t) => t.available) }))
    .filter((g) => g.themes.length > 0);
}

// Returns a flat array of available themes (used by ECOMMERCE picker which
// renders without category groups).
export function getAvailableFlat(vertical) {
  return getAvailableGroups(vertical).flatMap((g) => g.themes);
}

export function hasAnyAvailable(vertical) {
  return getAvailableGroups(vertical).length > 0;
}
